source('mp10_hypothesis_followup_v1/scripts/common.R');cg<-rd('respiratory_complex_gene_registry.tsv');cg<-cg[gene!='ATP5MH'];cg[,canonical_symbol:=gene];cg[gene=='NDUFA4',canonical_symbol:='COXFA4'];cg[gene=='ATP5MD',canonical_symbol:='ATP5MK'];cg[gene=='ATP5MPL',canonical_symbol:='ATP5MJ'];cg[,resource_version:='UniProt 2026_04 (04-Nov-2026); downloaded annotations retained']
b<-qread(file.path(OLD,'objects/pseudobulk.qs'),nthreads=1);ids<-b$profiles[profile_type=='Treg',profile_id];totals<-Matrix::rowSums(b$counts[,ids,drop=FALSE]);cg[,source_Treg_counts:=totals[gene]];cg[is.na(source_Treg_counts),source_Treg_counts:=0];setorder(cg,canonical_symbol,-source_Treg_counts,gene);cg[,representative_for_summary:=seq_len(.N)==1L,by=canonical_symbol];cg[,rule:='one fixed source feature per canonical subunit, largest total raw Treg counts (no effect or P selection); complete feature-level DE retained; no recounting or renormalization'];put(cg,'respiratory_complex_gene_registry.tsv')
